def candyCircle(ratings):
    n = len(ratings)
    m = ratings.index(min(ratings))
    b = ratings[m:] + ratings[:m]
    c = [1] * n
    for i in range(1, n):
        if b[i] > b[i - 1]:
            c[i] = c[i - 1] + 1
    for i in range(n - 1, -1, -1):
        nxt = (i + 1) % n
        if b[i] > b[nxt] and c[i] <= c[nxt]:
            c[i] = c[nxt] + 1
    return sum(c)
